<?php
session_start(); require_once 'db_connect.php';
if (!isset($_SESSION['user_id'])) { header('Location: login.php'); exit(); }
$userId=(int)$_SESSION['user_id'];
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_read'])) { $id=(int)$_POST['mark_read'];$stmt=$conn->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?');if($stmt){$stmt->bind_param('ii',$id,$userId);$stmt->execute();$stmt->close();} }
$stmt=$conn->prepare('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');
$rows=[];$ready=true;if($stmt){$stmt->bind_param('i',$userId);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}else{$ready=false;}
$role=$_SESSION['role']??'';$back=$role==='admin'?'admin_dashboard.php':($role==='faculty'?'teacher_dashboard.php':'student_dashboard.php');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications - Webyte</title><style>body{font:15px Arial,sans-serif;background:#f3f7f4;margin:0;padding:24px;color:#1e2b20}.panel{max-width:850px;margin:auto;background:white;padding:24px;border-radius:16px;box-shadow:0 8px 28px #0001}.item{padding:14px;border-bottom:1px solid #e6ece7}.unread{background:#f0faee}.muted{font-size:12px;color:#68766b}.btn{padding:8px 12px;border:0;border-radius:7px;background:#108a00;color:white;cursor:pointer}.back{display:inline-block;margin-bottom:14px;background:#108a00;color:white;padding:10px 14px;border-radius:8px;text-decoration:none}</style></head><body><div class="panel"><a class="back" href="<?=htmlspecialchars($back)?>">Back to Dashboard</a><h2>Notifications</h2><?php if(!$ready):?><p>Notifications are not configured yet. Apply the database migration, then reload this page.</p><?php elseif(!$rows):?><p>You have no notifications yet.</p><?php else:foreach($rows as $row):?><div class="item <?=$row['is_read']?'':'unread'?>"><strong><?=htmlspecialchars($row['title'])?></strong><p><?=nl2br(htmlspecialchars($row['message']))?></p><div class="muted"><?=htmlspecialchars($row['created_at'])?></div><?php if(!$row['is_read']):?><form method="post"><button class="btn" name="mark_read" value="<?=$row['id']?>">Mark as Read</button></form><?php endif;?></div><?php endforeach;endif;?></div></body></html>
